// Interactive robot viewer: robotai v1, our own humanoid (upper body + dynamic legs), one jointed model.
//   /models/robot_v1.glb is generated by cad/robot_v1.py in Blender. Every joint is an empty named
//   <side>_<joint> (or waist_yaw / spine / neck_yaw / neck_pitch) with identity rest rotation, so
//   rotation.x = pitch, rotation.z = roll, rotation.y = yaw. Materials: shell (white), drive (dark), metal, accent (glow).
// data-focus picks the framing: (none) whole robot, "arm" right-arm close-up, "legs" hips-to-feet close-up.
// Move buttons call robot3d_setMove(walk | run | box | backflip).
import * as THREE from "three";
import { OrbitControls } from "three/examples/jsm/controls/OrbitControls.js";
import { GLTFLoader } from "three/examples/jsm/loaders/GLTFLoader.js";

const MODEL = "/models/robot_v1.glb";
const HIP_HEIGHT = 0.98; // metres from the soles to the hip root (cad/legs.py LEG_LENGTH)

const el = document.getElementById("arm3d");
const status = document.getElementById("arm3d-status");
const FOCUS = el.dataset.focus || "home";

const css = (v) => getComputedStyle(document.documentElement).getPropertyValue(v).trim();
const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
el.appendChild(renderer.domElement);

const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(35, 1, 0.01, 30);
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.enableZoom = false;

scene.add(new THREE.HemisphereLight(0xffffff, 0x888899, 1.9));
const sun = new THREE.DirectionalLight(0xffffff, 2.4);
sun.position.set(1.5, 4, 2.5);
sun.castShadow = true;
sun.shadow.mapSize.set(1024, 1024);
Object.assign(sun.shadow.camera, { left: -2, right: 2, top: 3, bottom: -1, near: 0.5, far: 10 });
scene.add(sun);

// Ground: a soft disc that catches the robot's shadow, so jumps and flips read as moving over the floor.
const ground = new THREE.Mesh(new THREE.CircleGeometry(1.6, 64), new THREE.ShadowMaterial({ color: 0x000000, opacity: 0.35 }));
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);
const floorRing = new THREE.Mesh(
  new THREE.RingGeometry(1.2, 1.22, 96),
  new THREE.MeshBasicMaterial({ color: css("--line") || "#262a33", transparent: true, opacity: 0.8 })
);
floorRing.rotation.x = -Math.PI / 2;
floorRing.position.y = 0.001;
scene.add(floorRing);

const mats = {
  shell: new THREE.MeshStandardMaterial({ color: "#eef0f3", roughness: 0.5 }),
  drive: new THREE.MeshStandardMaterial({ color: "#2a2d34", roughness: 0.42, metalness: 0.25 }),
  metal: new THREE.MeshStandardMaterial({ color: "#9aa1ad", roughness: 0.3, metalness: 0.8 }),
  accent: new THREE.MeshStandardMaterial({ color: css("--accent") || "#2f5bea", emissive: css("--accent") || "#2f5bea", emissiveIntensity: 0.8, roughness: 0.3 }),
};
const glow = new THREE.MeshStandardMaterial({ color: css("--hw") || "#e07a2f", roughness: 0.4, emissive: css("--hw") || "#e07a2f", emissiveIntensity: 0.3 });

let robot = null;
const J = {}; // joints by name
const pivot = new THREE.Group(); // at the centre of mass, so flips rotate about the body
const rig = new THREE.Group();
pivot.add(rig);
scene.add(pivot);
const COM = 0.25; // centre of mass above the hip root (metres)

const manager = new THREE.LoadingManager();
manager.onProgress = (_, n, total) => { status.textContent = `Loading the robot… ${n}/${total}`; };
// Frame once everything has loaded (onProgress would otherwise overwrite the status line afterwards).
manager.onLoad = () => { if (!robot) return; pose(0); scene.updateMatrixWorld(true); frame(); };
new GLTFLoader(manager).load(MODEL, (g) => {
  robot = g.scene;
  robot.traverse((o) => {
    if (o.isMesh) {
      o.castShadow = true;
      o.material = mats[o.material?.name] || mats.shell;
      o.userData.base = o.material;
    } else if (o.name && o.name !== "Scene") {
      J[o.name] = o;
    }
  });
  rig.add(robot);
  robot.position.set(0, -COM, 0); // rig origin = centre of mass
  pivot.position.set(0, HIP_HEIGHT + COM, 0);
}, undefined, () => { status.textContent = "3D model couldn't load. Check your connection."; });

function frame(zoom = 1) {
  const box = new THREE.Box3();
  if (FOCUS === "arm") {
    box.setFromObject(J.right_shoulder_pitch);
    aim(box, new THREE.Vector3(-0.8, 0.15, 1), 1.3);
    status.textContent = "One arm, shoulder to fingertips · drag to rotate";
  } else if (FOCUS === "legs") {
    box.setFromObject(J.left_hip_yaw).union(new THREE.Box3().setFromObject(J.right_hip_yaw));
    aim(box, new THREE.Vector3(0.8, 0.2, 1), 1.5);
    status.textContent = "The legs · 7 joints each, hips to toes · drag to rotate";
  } else {
    box.setFromObject(robot);
    box.min.y = 0;
    aim(box, new THREE.Vector3(0.35, 0.15, 1), 1.75 * zoom);
    status.textContent = "robotai v1 · our own life-size humanoid · drag to rotate";
  }
}
function aim(box, dir, dist) {
  const c = box.getCenter(new THREE.Vector3()), size = box.getSize(new THREE.Vector3()).length();
  controls.target.copy(c);
  camera.position.copy(c).add(dir.normalize().multiplyScalar(size * dist));
}

// ---- joints ----
const set = (name, axis, v) => { const j = J[name]; if (j) j.rotation[axis] = v; };
const pitch = (n, v) => set(n, "x", v), roll = (n, v) => set(n, "z", v), yaw = (n, v) => set(n, "y", v);
const FINGERS = ["index", "middle", "ring", "pinky", "thumb"];
function hand(side, curl) { for (const f of FINGERS) for (const k of [1, 2, 3]) pitch(`${side}_${f}_${k}`, -curl * (f === "thumb" ? 0.6 : 1)); }
// Signs (robot faces +Z, Y up): negative hip/shoulder pitch swings a limb forward, positive knee bends it,
// negative elbow bends the forearm up, positive spine leans forward, negative finger pitch curls a finger.
function leg(side, hip, knee, ankle, toe = 0) {
  pitch(`${side}_hip_pitch`, hip); pitch(`${side}_knee`, knee); pitch(`${side}_ankle_pitch`, ankle); pitch(`${side}_toe`, toe);
}
function arm(side, shoulder, elbow, rollOut = 0.12) {
  pitch(`${side}_shoulder_pitch`, shoulder); pitch(`${side}_elbow`, elbow);
  roll(`${side}_shoulder_roll`, side === "left" ? rollOut : -rollOut);
}

// ---- moves ----
let move = "walk", moveStart = 0;
window.robot3d_setMove = (m) => {
  move = m;
  moveStart = performance.now() / 1000;
  if (robot && FOCUS === "home") frame(m === "backflip" ? 1.35 : 1);
};
const ease = (x) => x * x * (3 - 2 * x);
const clamp01 = (x) => Math.min(1, Math.max(0, x));

function pose(t) {
  const T = t - moveStart;
  pivot.rotation.set(0, 0, 0);
  pivot.position.y = HIP_HEIGHT + COM;
  pitch("spine", 0); yaw("waist_yaw", 0); yaw("neck_yaw", 0.35 * Math.sin(t * 0.4));
  hand("left", 0.35); hand("right", 0.35);

  if (FOCUS === "arm") {
    arm("right", -0.7, -1.1 - 0.15 * Math.sin(t * 0.6));
    yaw("right_wrist_yaw", 0.7 * Math.sin(t * 0.5));
    hand("right", 0.7 + 0.7 * Math.sin(t * 1.1));
    return;
  }
  if (move === "run") {
    for (const [side, k] of [["left", 0], ["right", Math.PI]]) {
      const ph = T * 6 + k;
      leg(side, -0.8 * Math.sin(ph), 0.3 + 1.2 * Math.max(0, Math.sin(ph + 0.9)), -0.25 * Math.sin(ph) - 0.1, 0.35 * Math.max(0, -Math.sin(ph)));
      arm(side === "left" ? "right" : "left", -0.7 * Math.sin(ph), -1.5);
    }
    pitch("spine", 0.12);
    pivot.position.y += 0.035 * Math.abs(Math.sin(T * 6)) - 0.03;
  } else if (move === "box") {
    const bounce = 0.02 * Math.sin(T * 5);
    leg("left", -0.45, 0.6, -0.15);
    leg("right", 0.12, 0.5, -0.4, 0.4);
    const jab = Math.max(0, Math.sin(T * 3)) ** 6;       // left jab every ~2 s
    const cross = Math.max(0, Math.sin(T * 3 - 2.2)) ** 6; // right cross after it
    arm("left", -1.0 - 0.5 * jab, -1.9 + 1.7 * jab, 0.25);
    arm("right", -0.9 - 0.6 * cross, -2.0 + 1.8 * cross, 0.3);
    hand("left", 1.5); hand("right", 1.5);                   // fists
    yaw("waist_yaw", 0.25 * cross - 0.15 * jab);
    pitch("spine", 0.15);
    pivot.rotation.y = -0.4;                                 // bladed stance
    pivot.position.y += -0.07 + bounce;
  } else if (move === "backflip") {
    // 2.8 s: stand, load, jump, tuck + rotate, land, recover. The robot rises off the floor and rotates
    // about its centre of mass; the camera and floor stay still.
    const u = T % 2.8;
    const load = u < 0.6 ? ease(clamp01((u - 0.25) / 0.35)) : u < 0.7 ? 1 - ease((u - 0.6) / 0.1) : 0;
    const air = clamp01((u - 0.7) / 0.9);                    // 0.7 .. 1.6 s in the air
    const inAir = u > 0.7 && u < 1.6;
    const land = u >= 1.6 && u < 2.1 ? Math.sin(Math.PI * (u - 1.6) / 0.5) : 0;
    const tuck = inAir ? Math.sin(Math.PI * air) : 0;
    const bend = Math.max(load * 0.9, tuck * 1.7, land * 0.7);
    for (const side of ["left", "right"]) {
      leg(side, -bend * 0.9, bend * 1.5, -bend * 0.55);
      // arms swing back to load, whip overhead to launch, grab the shins in the tuck
      const sh = load > 0 ? 0.7 * load : inAir ? -2.8 + 1.4 * tuck : -0.4 * land;
      arm(side, sh, inAir ? -0.3 - 1.2 * tuck : -0.3);
    }
    pitch("spine", load * 0.35 + tuck * 0.5);
    pivot.position.y += -0.28 * Math.max(load, land) + (inAir ? 1.05 * Math.sin(Math.PI * air) : 0);
    pivot.rotation.x = inAir ? -2 * Math.PI * ease(air) : 0; // one full backward rotation
  } else {
    for (const [side, k] of [["left", 0], ["right", Math.PI]]) {
      const ph = T * 2.4 + k;
      leg(side, -0.4 * Math.sin(ph), 0.05 + 0.6 * Math.max(0, Math.sin(ph + 0.8)), -0.15 * Math.sin(ph));
      arm(side === "left" ? "right" : "left", -0.35 * Math.sin(ph), -0.35);
    }
    pivot.position.y += 0.012 * Math.abs(Math.sin(T * 2.4)) - 0.01;
  }
}

// Highlight API for the part lists: match mesh / joint names by list, prefix or regex; null clears.
window.robot3d = {
  highlight(part) {
    robot?.traverse((o) => {
      if (!o.isMesh) return;
      const name = `${o.name} ${o.parent?.name || ""}`;
      const hit = part && ((part.links || []).some((l) => name.includes(l))
        || (part.prefix && name.startsWith(part.prefix)) || (part.match && new RegExp(part.match).test(name)));
      o.material = hit ? glow : o.userData.base;
    });
  },
};

function resize() {
  const w = el.clientWidth, h = el.clientHeight;
  renderer.setSize(w, h, false);
  camera.aspect = w / h;
  camera.updateProjectionMatrix();
}
new ResizeObserver(resize).observe(el);

const still = matchMedia("(prefers-reduced-motion: reduce)").matches;
renderer.setAnimationLoop((ms) => {
  if (robot) pose(still ? 0 : ms / 1000);
  controls.update();
  renderer.render(scene, camera);
});
